<?php
/** Proton Lumo: a privacy-first assistant, how its privacy works, features, good use and limits. */

return [
    'id' => 'lumo', 'family' => 'assistants', 'after' => null,
    'title' => L('Proton Lumo', 'Proton Lumo'), 'short' => L('Lumo', 'Lumo'), 'level' => L('Base', 'Basics'),
    'desc' => L('L’assistente di Proton pensato per la privacy: cronologia cifrata, niente addestramento sulle chat, modalità fantasma, ricerca web facoltativa, file e Proton Drive.', 'Proton’s privacy-first assistant: encrypted history, no training on chats, ghost mode, optional web search, files and Proton Drive.'),
    'lessons' => [
        lesson('intro', L('Che cos’è Lumo', 'What Lumo is'), [
            P('**Lumo** è l’assistente AI di **Proton**, l’azienda svizzera di Proton Mail, Proton VPN e Proton Drive, lanciato nel 2025. La sua idea centrale è la **privacy**: le conversazioni non servono per addestrare modelli né per la pubblicità, e la cronologia salvata è protetta da cifratura.', '**Lumo** is the AI assistant from **Proton**, the Swiss company behind Proton Mail, Proton VPN and Proton Drive, launched in 2025. Its core idea is **privacy**: conversations are not used to train models or for advertising, and saved history is protected by encryption.'),
            P('Lumo funziona con modelli linguistici **open source**, eseguiti sui server europei di Proton. Si usa dal web e dalle app per telefono; si può provare anche senza account, mentre con un account Proton si salvano le chat e si sbloccano più funzioni, con un piano gratuito e uno a pagamento.', 'Lumo runs on **open-source** language models, executed on Proton’s European servers. You use it from the web and phone apps; you can try it without an account, while a Proton account lets you save chats and unlocks more features, with a free and a paid plan.'),
        ], [
            Q('i1', L('Quale azienda ha creato Lumo?', 'Which company created Lumo?'), ['Proton', 'Google', 'OpenAI', 'Mistral AI'], 0, L('Quella di Proton Mail.', 'The Proton Mail company.')),
            Q('i2', L('Qual è l’idea centrale di Lumo?', 'What is Lumo’s core idea?'), [L('La privacy', 'Privacy'), L('La pubblicità mirata', 'Targeted ads'), L('I videogiochi', 'Video games'), L('La generazione di video', 'Video generation')], 0, L('Niente addestramento né pubblicità con le chat.', 'No training or ads from chats.')),
            Q('i3', L('Su quali modelli si basa Lumo?', 'Which models does Lumo rely on?'), [L('Modelli open source', 'Open-source models'), L('Solo GPT', 'Only GPT'), L('Nessun modello', 'No model'), L('Modelli segreti di Proton Mail', 'Secret Proton Mail models')], 0, L('Eseguiti sui server di Proton.', 'Run on Proton’s servers.')),
        ], task('text', L('Scrivi due motivi per cui una persona attenta alla privacy potrebbe scegliere Lumo, uno per riga che inizia con `-`.', 'Write two reasons why a privacy-minded person might choose Lumo, one per line starting with `-`.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due motivi', 'Two reasons')), re('addestr|train|pubblicit|ads|advert|cifr|encrypt|log', L('Parli di addestramento, pubblicità, cifratura o log', 'You mention training, ads, encryption or logs'))], '', "- le chat non vengono usate per addestrare i modelli\n- la cronologia salvata è cifrata"), [
            dMatch(pMatch(), [['Proton', L('Azienda svizzera', 'Swiss company')], ['Lumo', L('Assistente AI', 'AI assistant')], [L('Open source', 'Open source'), L('I modelli usati', 'The models used')], [L('Server europei', 'European servers'), L('Dove girano i modelli', 'Where the models run')]], L('Lumo in breve.', 'Lumo in short.')),
            dFlash(pFlash(), [[L('Lumo è sviluppato da Proton', 'Lumo is developed by Proton'), true], [L('Lumo usa le chat per la pubblicità', 'Lumo uses chats for advertising'), false], [L('Lumo si può provare senza account', 'Lumo can be tried without an account'), true], [L('Lumo è un prodotto di Google', 'Lumo is a Google product'), false]], L('Un assistente riservato.', 'A discreet assistant.')),
        ]),
        lesson('privacy', L('Come funziona la privacy', 'How the privacy works'), [
            P('Le chat salvate sono protette con la **cifratura ad accesso zero** di Proton: sono cifrate con una chiave legata al tuo account, così sul server restano illeggibili anche per Proton. Proton dichiara di **non conservare log** delle conversazioni e di non condividerle con terze parti.', 'Saved chats are protected with Proton’s **zero-access encryption**: they are encrypted with a key tied to your account, so on the server they stay unreadable even to Proton. Proton states it **keeps no logs** of conversations and does not share them with third parties.'),
            P('La **modalità fantasma** apre chat che spariscono quando le chiudi, senza lasciare cronologia. Ricorda però un limite tecnico: per rispondere, il modello deve elaborare il testo della domanda sul server. La privacy riguarda soprattutto cosa viene **conservato**, **usato** e **condiviso** dopo.', '**Ghost mode** opens chats that disappear when you close them, leaving no history. Remember a technical limit, though: to answer, the model must process the question’s text on the server. Privacy is mainly about what is **kept**, **used** and **shared** afterwards.'),
        ], [
            Q('p1', L('Che cosa significa cifratura ad accesso zero?', 'What does zero-access encryption mean?'), [L('Le chat salvate sono illeggibili anche per Proton', 'Saved chats are unreadable even to Proton'), L('Nessuno può accedere a Lumo', 'Nobody can access Lumo'), L('Non serve una password', 'No password is needed'), L('Lumo funziona offline', 'Lumo works offline')], 0, L('La chiave è legata al tuo account.', 'The key is tied to your account.')),
            Q('p2', L('Che cosa fa la modalità fantasma?', 'What does ghost mode do?'), [L('Le chat spariscono quando le chiudi', 'Chats vanish when you close them'), L('Nasconde l’app dal telefono', 'Hides the app from the phone'), L('Cambia la voce', 'Changes the voice'), L('Disattiva il modello', 'Turns off the model')], 0, L('Nessuna cronologia.', 'No history.')),
            Q('p3', L('Il modello deve comunque leggere la domanda per rispondere?', 'Must the model still read the question to answer?'), [L('Sì, la elabora sul server', 'Yes, it processes it on the server'), L('No, mai', 'No, never'), L('Solo il lunedì', 'Only on Mondays'), L('Solo se è breve', 'Only if it is short')], 0, L('La privacy riguarda cosa succede dopo.', 'Privacy is about what happens afterwards.')),
        ], task('text', L('Spiega in due frasi la differenza tra una chat normale salvata in Lumo e una in **modalità fantasma**.', 'Explain in two sentences the difference between a normal saved Lumo chat and one in **ghost mode**.'), '', [re('fantasma|ghost', L('Citi la modalità fantasma', 'You mention ghost mode')), re('cifrat|encrypt|salvat|saved|cronologia|history', L('Parli della chat salvata', 'You talk about the saved chat')), re('spar|vanish|disappear|cancell|delet', L('Dici che la chat fantasma sparisce', 'You say the ghost chat disappears'))], '', 'Una chat normale resta nella cronologia, salvata e cifrata con la chiave del mio account. In modalità fantasma la chat sparisce quando la chiudo e non resta nella cronologia.'), [
            dMatch(pMatch(), [[L('Accesso zero', 'Zero-access'), L('Illeggibile anche per Proton', 'Unreadable even to Proton')], [L('Nessun log', 'No logs'), L('Le conversazioni non vengono registrate', 'Conversations are not logged')], [L('Modalità fantasma', 'Ghost mode'), L('Chat che spariscono', 'Vanishing chats')], [L('Elaborazione', 'Processing'), L('Il modello legge la domanda per rispondere', 'The model reads the question to answer')]], L('I pilastri della privacy di Lumo.', 'Lumo’s privacy pillars.')),
            dFlash(pFlash(), [[L('Le chat salvate di Lumo sono cifrate', 'Lumo’s saved chats are encrypted'), true], [L('La modalità fantasma conserva tutto per sempre', 'Ghost mode keeps everything forever'), false], [L('Il modello deve elaborare la domanda per rispondere', 'The model must process the question to answer'), true], [L('Proton vende le chat agli inserzionisti', 'Proton sells chats to advertisers'), false]], L('Privacy, con i suoi limiti tecnici.', 'Privacy, with its technical limits.')),
        ]),
        lesson('features', L('Funzioni', 'Features'), [
            P('Lumo può **analizzare file** caricati (documenti, fogli di calcolo, immagini), lavorare con i file di **Proton Drive** e fare **ricerche sul web** per informazioni recenti. La ricerca web è **facoltativa**: la attivi tu quando serve, e le ricerche passano attraverso motori di ricerca attenti alla privacy.', 'Lumo can **analyse uploaded files** (documents, spreadsheets, images), work with **Proton Drive** files and **search the web** for recent information. Web search is **optional**: you turn it on when needed, and searches go through privacy-respecting search engines.'),
            P('Si possono dare **istruzioni personalizzate** e usarlo per riassumere, scrivere, tradurre, programmare e fare brainstorming, come gli altri assistenti. Il piano a pagamento offre limiti più alti e funzioni in più, come una cronologia illimitata e caricamenti più grandi.', 'You can set **custom instructions** and use it to summarise, write, translate, code and brainstorm, like other assistants. The paid plan offers higher limits and extra features, such as unlimited history and larger uploads.'),
        ], [
            Q('f1', L('La ricerca web di Lumo è sempre attiva?', 'Is Lumo’s web search always on?'), [L('No, è facoltativa', 'No, it is optional'), L('Sì, sempre', 'Yes, always'), L('Non esiste', 'It does not exist'), L('Solo di notte', 'Only at night')], 0, L('La attivi quando serve.', 'You turn it on when needed.')),
            Q('f2', L('Con quale servizio Proton si integra Lumo per i file?', 'Which Proton service does Lumo integrate with for files?'), ['Proton Drive', 'Proton VPN', 'Proton Pass', 'Proton Calendar'], 0, L('Oltre ai file caricati.', 'Besides uploaded files.')),
            Q('f3', L('Che cosa offre il piano a pagamento?', 'What does the paid plan offer?'), [L('Limiti più alti e funzioni in più', 'Higher limits and extra features'), L('Meno privacy', 'Less privacy'), L('Pubblicità', 'Ads'), L('Niente', 'Nothing')], 0, L('La privacy resta la stessa.', 'Privacy stays the same.')),
        ], task('text', L('Scrivi una richiesta per Lumo che chieda di riassumere un documento caricato in **5 punti** e di indicare **3 domande** da fare al relatore.', 'Write a Lumo request asking to summarise an uploaded document in **5 points** and to list **3 questions** to ask the speaker.'), '', [re('document|file|allegat|caricat|upload', L('Parli del documento', 'You mention the document')), re('5\s*(punti|points)|cinque punti|five points', L('Cinque punti', 'Five points')), re('3\s*(domande|questions)|tre domande|three questions', L('Tre domande', 'Three questions'))], '', 'Riassumi il documento caricato in 5 punti e suggeriscimi 3 domande da fare al relatore.'), [
            dMatch(pMatch(), [[L('File caricati', 'Uploaded files'), L('Documenti e immagini da analizzare', 'Documents and images to analyse')], ['Proton Drive', L('I tuoi file nel cloud cifrato', 'Your files in the encrypted cloud')], [L('Ricerca web', 'Web search'), L('Facoltativa, attenta alla privacy', 'Optional, privacy-respecting')], [L('Istruzioni personalizzate', 'Custom instructions'), L('Come vuoi le risposte', 'How you want answers')]], L('Cosa sa fare Lumo.', 'What Lumo can do.')),
            dFlash(pFlash(), [[L('Lumo può analizzare un foglio di calcolo', 'Lumo can analyse a spreadsheet'), true], [L('La ricerca web non si può disattivare', 'Web search cannot be turned off'), false], [L('Lumo si integra con Proton Drive', 'Lumo integrates with Proton Drive'), true], [L('Il piano a pagamento riduce la privacy', 'The paid plan reduces privacy'), false]], L('Funzioni con discrezione.', 'Features with discretion.')),
        ]),
        lesson('use', L('Quando usarlo, e i limiti', 'When to use it, and the limits'), [
            P('Lumo è una buona scelta quando i contenuti sono **personali o riservati**: bozze di email delicate, appunti di lavoro, documenti che non vuoi finiscano nell’addestramento di un modello. Per i compiti più difficili (problemi complessi, codice di grandi progetti) i modelli più grandi di altri servizi possono essere più capaci.', 'Lumo is a good choice when content is **personal or confidential**: sensitive email drafts, work notes, documents you do not want to end up in a model’s training. For the hardest tasks (complex problems, code for large projects) other services’ larger models may be more capable.'),
            P('Anche con un assistente attento alla privacy valgono le buone abitudini: verifica fatti e numeri, non incollare dati di altre persone senza motivo, e ricorda che la privacy del servizio non sostituisce le regole della tua azienda o scuola.', 'Even with a privacy-minded assistant the good habits apply: verify facts and numbers, do not paste other people’s data without reason, and remember the service’s privacy does not replace your company’s or school’s rules.'),
            Tip('Una strategia comune: usare un assistente attento alla privacy per i contenuti delicati e altri strumenti per i compiti pubblici o molto tecnici.', 'A common strategy: use a privacy-minded assistant for sensitive content and other tools for public or highly technical tasks.'),
        ], [
            Q('u1', L('Per quale contenuto Lumo è particolarmente adatto?', 'For which content is Lumo particularly suited?'), [L('Contenuti personali o riservati', 'Personal or confidential content'), L('Solo giochi', 'Only games'), L('Solo immagini pubbliche', 'Only public images'), L('Nessuno', 'None')], 0, L('Non finiscono nell’addestramento.', 'They do not end up in training.')),
            Q('u2', L('Un limite possibile di Lumo è…', 'A possible limit of Lumo is…'), [L('Sui compiti più difficili altri modelli possono essere più capaci', 'On the hardest tasks other models may be more capable'), L('Non funziona sul telefono', 'It does not work on phones'), L('Non capisce l’italiano', 'It does not understand Italian'), L('Pubblica le chat', 'It publishes chats')], 0, L('Dipende dai modelli disponibili.', 'It depends on the models available.')),
            Q('u3', L('La privacy di Lumo sostituisce le regole della tua azienda?', 'Does Lumo’s privacy replace your company’s rules?'), [L('No', 'No'), L('Sì, sempre', 'Yes, always'), L('Solo per le email', 'Only for email'), L('Solo nel fine settimana', 'Only at weekends')], 0, L('Le regole interne restano.', 'Internal rules still apply.')),
        ], task('text', L('Per ciascun compito indica `Lumo` o `altro`, uno per riga come `compito: scelta`. Compiti: `riscrivere una mail delicata al medico`, `progettare l’architettura di un’app con migliaia di file`.', 'For each task write `Lumo` or `other`, one per line as `task: choice`. Tasks: `rewrite a sensitive email to the doctor`, `design the architecture of an app with thousands of files`.'), '', [re('(medico|doctor)[^:\n]*:\s*Lumo', L('La mail delicata va su Lumo', 'The sensitive email goes to Lumo')), re('(architettura|architecture)[^:\n]*:\s*(altro|other)', L('Il compito tecnico enorme va su un altro strumento', 'The huge technical task goes elsewhere'))], '', "riscrivere una mail delicata al medico: Lumo\nprogettare l’architettura di un’app con migliaia di file: altro"), [
            dMatch(pMatch(), [[L('Mail delicata', 'Sensitive email'), 'Lumo'], [L('Appunti riservati', 'Confidential notes'), 'Lumo'], [L('Verifica', 'Verification'), L('Fatti e numeri importanti', 'Important facts and numbers')], [L('Regole aziendali', 'Company rules'), L('Valgono sempre', 'Always apply')]], L('Lo strumento giusto.', 'The right tool.')),
            dFlash(pFlash(), [[L('Anche con Lumo conviene verificare i fatti', 'With Lumo too it pays to verify facts'), true], [L('Con un assistente privato si può incollare qualsiasi dato altrui', 'With a private assistant you can paste anyone’s data'), false], [L('Si possono usare strumenti diversi per compiti diversi', 'Different tools can be used for different tasks'), true], [L('Lumo è sempre il più capace su ogni compito', 'Lumo is always the most capable at everything'), false]], L('Scelte consapevoli.', 'Informed choices.')),
        ]),
    ],
];
